"""Read trades."""

import shutil


class Reader:
    """Read trades through a scratch copy."""

    def read(self, path: str) -> list[str]:
        """Copy path to a scratch file and return no rows."""
        self._copy(path)
        return []

    def _copy(self, path: str) -> None:
        """Copy path to a scratch file."""
        shutil.copy(path, path + ".bak")


def read_trades(path: str) -> list[str]:
    """Read the trades at path."""
    return Reader.read(Reader(), path)
